function(){ 
    //logger.info("------TESTING DATE PREPROCESSOR");
    var moment = require('moment');
    
    if (document[field.name] && Array.isArray(document[field.name]) ) {
        var saveValue = document[field.name];
        //**************************************
        var isInValid = false;
        for(var i = 0; i < document[field.name].length; i++){
            if(document[field.name][i].createdDate) {
                var date = moment(document[field.name][i].createdDate, ["DD/MM/YYYY hh:mm a", "DD/MM/YYYY", "hh:mm a","DD/MM/YY","DD/MM/YY hh:mm a","DD/MM",moment.ISO_8601], true);
                if (date.isValid()) {
                    document[field.name][i].createdDate = date.toDate();
                } else {
                    isInValid = true;
                    break;
                }
            }
            if(document[field.name][i].modifiedDate) {
                var date = moment(document[field.name][i].modifiedDate, ["DD/MM/YYYY hh:mm a", "DD/MM/YYYY", "hh:mm a","DD/MM/YY","DD/MM/YY hh:mm a","DD/MM",moment.ISO_8601], true);
                if (date.isValid()) {
                    document[field.name][i].modifiedDate = date.toDate();
                } else {
                    isInValid = true;
                    break;
                }
            }
            if(document[field.name][i].comments && Array.isArray(document[field.name][i].comments)){
                for(var j = 0; j < document[field.name][i].comments.length; j++){
                    if(document[field.name][i].comments[j].createdDate){
                        var dateComment = moment(document[field.name][i].comments[j].createdDate, ["DD/MM/YYYY hh:mm a", "DD/MM/YYYY", "hh:mm a","DD/MM/YY","DD/MM/YY hh:mm a","DD/MM",moment.ISO_8601], true);
                        if (dateComment.isValid()) {
                            document[field.name][i].comments[j].createdDate = dateComment.toDate();
                        } else {
                            isInValid = true;
                            break;
                        }
                    }
                }
            }
            if(document[field.name][i].notesHistory && Array.isArray(document[field.name][i].notesHistory)){
                for(var j = 0; j < document[field.name][i].notesHistory.length; j++){
                    if(document[field.name][i].notesHistory[j].createdDate){
                        var dateComment = moment(document[field.name][i].notesHistory[j].createdDate, ["DD/MM/YYYY hh:mm a", "DD/MM/YYYY", "hh:mm a","DD/MM/YY","DD/MM/YY hh:mm a","DD/MM",moment.ISO_8601], true);
                        if (dateComment.isValid()) {
                            document[field.name][i].notesHistory[j].createdDate = dateComment.toDate();
                        } else {
                            isInValid = true;
                            break;
                        }
                    }
                    if(document[field.name][i].notesHistory[j].modifiedDate){
                        var dateComment = moment(document[field.name][i].notesHistory[j].modifiedDate, ["DD/MM/YYYY hh:mm a", "DD/MM/YYYY", "hh:mm a","DD/MM/YY","DD/MM/YY hh:mm a","DD/MM",moment.ISO_8601], true);
                        if (dateComment.isValid()) {
                            document[field.name][i].notesHistory[j].modifiedDate = dateComment.toDate();
                        } else {
                            isInValid = true;
                            break;
                        }
                    }
                }
            }
            if(isInValid){ break; }
        }
        if(isInValid) {
            var errMsg = field.componentName + " field named " + field.name +
                    " has invalid value \"" + saveValue + "\"";
            logger.error("Preprocessing Failure : " + errMsg);
            return null;
        }
    } else {
        return document;
    }
}

