function convertToDate(field, document){

    var value;

    if(!!document[field.name] && Array.isArray(document[field.name])){
        value = document[field.name];
        for(var i = 0; i < document[field.name].length; i++){
            if(document[field.name][i].createdDate && (typeof document[field.name][i].createdDate === "string")){
                document[field.name][i].createdDate = new Date(document[field.name][i].createdDate);
            }
            if(document[field.name][i].modifiedDate && (typeof document[field.name][i].modifiedDate === "string")){
                document[field.name][i].modifiedDate = new Date(document[field.name][i].modifiedDate);
            }
            if(document[field.name][i].comments && Array.isArray(document[field.name][i].comments) ) {
                for(var j = 0; j < document[field.name][i].comments; j++) {
                    if(document[field.name][i].comments[j].createdDate && (typeof document[field.name][i].comments[j].createdDate === "string")){
                        document[field.name][i].comments[j].createdDate = new Date(document[field.name][i].comments[j].createdDate);
                    }
                }
            }
            if(document[field.name][i].notesHistory && Array.isArray(document[field.name][i].notesHistory) ) {
                for(var j = 0; j < document[field.name][i].notesHistory; j++) {
                    if(document[field.name][i].notesHistory[j].createdDate && (typeof document[field.name][i].notesHistory[j].createdDate === "string")){
                        document[field.name][i].notesHistory[j].createdDate = new Date(document[field.name][i].notesHistory[j].createdDate);
                    }
                    if(document[field.name][i].notesHistory[j].modifiedDate && (typeof document[field.name][i].notesHistory[j].modifiedDate === "string")){
                        document[field.name][i].notesHistory[j].modifiedDate = new Date(document[field.name][i].notesHistory[j].modifiedDate);
                    }
                }
            }
        }
        document[field.name] = value;
    }

    return value;
    

}

serverPreprocessorFunction:
function(){ 
    if (document[field.name] !== null && document[field.name] !== "") {
		var saveValue = document[field.name];
		var errMsg = field.componentName + " field named " + field.name +
			" has invalid value \"" + saveValue + "\"";
		var typeOfField = typeof document[field.name];
		if (typeOfField === 'number' || typeOfField === 'undefined') {
			return document;
		} else {
			try {
				var numeric = parseFloat(document[field.name]);
				if (isNaN(numeric)) {
					logger.error("Preprocessing Failure : " + errMsg);
					 return null;
				} else {
					document[field.name] = numeric;
					return document;
				}
			} catch (err) {
				logger.error("Preprocessing Failure : " + errMsg);
				 return null;
			}
			
		}
	} else {
	    delete document[field.name];
	    return document;
    }
}

